private const val COLLAPSED_EVENT_COUNT = 7

/**
 * `context_vault.event_log`, grouped as "last 30 days" -- the summary line above the individual
 * entries is `context_vault.thirty_day_trend_timeline`, a narrative recap of the same window.
 * Each entry's pill color comes from its own `direction` (BULLISH/BEARISH/NEUTRAL), not `kind` --
 * `kind` is just the short category label shown inside the pill (e.g. "RSI", "52W_HIGH").
 *
 * Collapsed to the latest 7 entries by default -- "Show all" expands to the full (up to 30-day)
 * list, "Show latest" collapses back. The log is append-only and already chronological (oldest
 * first, per the backend's own module doc), so "latest" is the tail of the list (`takeLast`), not
 * the head. Local, non-persisted UI state -- resets on navigating away and back, same as every
 * other expand/collapse toggle on this screen.
 *
 * Collapsing back to 7 shrinks this section a lot -- without [BringIntoViewRequester], the parent
 * `LazyColumn`'s scroll offset doesn't change, so the viewport stays wherever it was and can land
 * on whatever section now scrolled up into that spot (Direct News, in practice), which reads as
 * the Timeline vanishing rather than collapsing. `bringIntoView()` on collapse scrolls the section
 * back into the viewport -- the requester sits on just the title row specifically, not the whole
 * section, since `bringIntoView()` only scrolls the minimum amount needed to satisfy whatever
 * bounds it's attached to: on the full section, that minimum was often already satisfied by a
 * sliver of the last row or the button still poking into the viewport, so it barely scrolled at
 * all. Anchoring to the title forces the scroll all the way to the section's top.
 */
@Composable
fun EventLog(contextVault: DomainContextVault?, modifier: Modifier = Modifier) {
    val events = contextVault?.eventLog.orEmpty()
    if (events.isEmpty() && contextVault?.thirtyDayTrendTimeline == null) return

    val pulseColors = LocalPulseColors.current
    var showAll by remember { mutableStateOf(false) }
    val visibleEvents = if (showAll || events.size <= COLLAPSED_EVENT_COUNT) events else events.takeLast(COLLAPSED_EVENT_COUNT)
    val bringIntoViewRequester = remember { BringIntoViewRequester() }
    val coroutineScope = rememberCoroutineScope()

    Column(modifier = modifier.fillMaxWidth()) {
        Box(modifier = Modifier.bringIntoViewRequester(bringIntoViewRequester)) {
            SectionDividerLabel(title = stringResource(id = R.string.stock_detail_technical_timeline_title))
        }
        Spacer()

        contextVault?.thirtyDayTrendTimeline?.let {
            Text(text = it, style = MaterialTheme.typography.bodyMedium, color = pulseColors.onSurfaceMuted)
            Spacer()
        }

        visibleEvents.forEachIndexed { index, event ->
            EventRow(event)
            if (index != visibleEvents.lastIndex) {
                HorizontalDivider(
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.1f),
                    thickness = dimensionResource(id = R.dimen.border_thin),
                    modifier = Modifier.padding(vertical = dimensionResource(id = R.dimen.padding_medium))
                )
            }
        }

        if (events.size > COLLAPSED_EVENT_COUNT) {
            Spacer()
            Text(
                text = stringResource(id = if (showAll) R.string.stock_detail_show_latest else R.string.stock_detail_show_all),
                style = MaterialTheme.typography.labelMedium.copy(fontWeight = FontWeight.Bold),
                color = pulseColors.accentPrimary,
                modifier = Modifier.clickable {
                    val wasShowingAll = showAll
                    showAll = !showAll
                    if (wasShowingAll) {
                        coroutineScope.launch { bringIntoViewRequester.bringIntoView() }
                    }
                }
            )
        }
    }
}

/**
 * `date` + `kind` pill share a line (a short date and a short label always fit comfortably); the
 * event's own `text` goes on its own full-width line below rather than continuing that same row --
 * with a date column, a pill, and body text all competing for one row, the description's leftover
 * space shrank to whatever the date+pill didn't use, which is what was making it wrap awkwardly/
 * overflow on longer entries. `event.date` comes over the wire as an ISO `yyyy-MM-dd` string (e.g.
 * "2026-07-28"); `toLongDateString()` renders that as "July 28" instead.
 */
@Composable
private fun EventRow(event: DomainEventLogItem) {
    val pulseColors = LocalPulseColors.current
    val (pillColor, textColor) = when (event.direction?.uppercase(Locale.US)) {
        "BULLISH" -> pulseColors.signalBullishPill to pulseColors.signalBullishText
        "BEARISH" -> pulseColors.signalBearishPill to pulseColors.signalBearishText
        else -> pulseColors.signalNeutralPill to pulseColors.signalNeutralText
    }

    Column {
        Row(verticalAlignment = Alignment.CenterVertically) {
            event.date?.let {
                Text(
                    text = it.toLongDateString(),
                    style = MaterialTheme.typography.labelSmall,
                    color = pulseColors.onSurfaceMuted
                )
                androidx.compose.foundation.layout.Spacer(modifier = Modifier.width(dimensionResource(id = R.dimen.padding_medium)))
            }
            event.kind?.let {
                SignalPill(text = it.replace('_', ' ').uppercase(Locale.US), pillColor = pillColor, contentColor = textColor)
            }
        }
        event.text?.let {
            androidx.compose.foundation.layout.Spacer(modifier = Modifier.height(dimensionResource(id = R.dimen.padding_small)))
            Text(
                text = it,
                style = MaterialTheme.typography.bodyMedium,
                color = MaterialTheme.colorScheme.onSurface,
                modifier = Modifier.fillMaxWidth()
            )
        }
    }
}

@Composable
private fun Spacer() {
    androidx.compose.foundation.layout.Spacer(modifier = Modifier.height(dimensionResource(id = R.dimen.padding_medium)))
}

